// in translations.ts stay readable; merged into `dicts` there. `en` is the
// master/fallback — any key missing from a language falls back to English, so
// languages may be filled in incrementally without leaking raw keys.
// Machine-assisted translations; native review recommended before production.
// ============================================================================
