  "vn.dash.howPaidBody": "ನಾಗರಿಕರು ತಮ್ಮ ಪ್ರಯೋಜನವನ್ನು ನೇರವಾಗಿ ಇ-ರೂಪಾಯಿಯಲ್ಲಿ ನಿಮ್ಮೊಂದಿಗೆ ಖರ್ಚು ಮಾಡುತ್ತಾರೆ. ಅವರು ವಿತರಣೆ ಖಚಿತಪಡಿಸಿದ ನಂತರ, ಒಬ್ಬ ನಿರ್ವಾಹಕರು ನಿಮ್ಮ ಪರವಾಗಿ ವಿಮೋಚನೆ ಸಲ್ಲಿಸುತ್ತಾರೆ ಮತ್ತು ರಿಸರ್ವ್ ಬ್ಯಾಂಕ್ ಅದನ್ನು ನಗದು ಆಗಿ ಇತ್ಯರ್ಥಪಡಿಸುತ್ತದೆ — ನೋಡಿ",
