  "vn.enrol.notEnrolledBody": "ನಿಮ್ಮ ಖಾತೆ ಅನುಮೋದಿತ ಮಾರಾಟಗಾರ ದಾಖಲೆಯೊಂದಿಗೆ ಲಿಂಕ್ ಆಗಿಲ್ಲ. ಮಾರಾಟಗಾರ ನೋಂದಣಿಯನ್ನು ZK ವ್ಯಾಪಾರ-ರಿಜಿಸ್ಟ್ರಿ ಪರಿಶೀಲನೆಯ ನಂತರ ಯೋಜನೆ ನಿರ್ವಾಹಕರು ಆರಂಭಿಸುತ್ತಾರೆ.",
  "vn.enrol.howTitle": "ನೋಂದಣಿ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ",
  "vn.enrol.step1t": "ವ್ಯಾಪಾರ ರಿಜಿಸ್ಟ್ರಿ ಹೊಂದಾಣಿಕೆ",
  "vn.enrol.step1d": "ನಿಮ್ಮ ವ್ಯಾಪಾರ ರುಜುವಾತುಗಳನ್ನು ಯೋಜನೆಯ ವಲಯಕ್ಕೆ ನಿರ್ವಹಿಸಲಾದ ಸರ್ಕಾರಿ ವ್ಯಾಪಾರ ರಿಜಿಸ್ಟ್ರಿಯೊಂದಿಗೆ ಹೊಂದಿಸಲಾಗುತ್ತದೆ.",
  "vn.enrol.step2t": "ಜೀರೋ-ನಾಲೆಜ್ ಪ್ರೂಫ್",
  "vn.enrol.step2d": "ನಿಮ್ಮ ವ್ಯಾಪಾರ ವರ್ಗಕ್ಕೆ ಅರ್ಹವಾಗಿದೆ ಎಂಬ ಪುರಾವೆ ರಚಿಸಲಾಗುತ್ತದೆ — ನಿಮ್ಮ ಖಾಸಗಿ ವ್ಯಾಪಾರ ಡೇಟಾವನ್ನು ಬಹಿರಂಗಪಡಿಸದೆ.",
  "vn.enrol.step3t": "ಆನ್-ಚೈನ್ ರಿಲೇ",
  "vn.enrol.step3d": "ಒಬ್ಬ ಯೋಜನೆ ನಿರ್ವಾಹಕರು ಪರಿಶೀಲಿಸಿದ ಪುರಾವೆಯನ್ನು ರಿಲೇ ಮಾಡುತ್ತಾರೆ, ನಿಮ್ಮ ವರ್ಗ ಸೇವೆ ಸಲ್ಲಿಸಬಹುದಾದ ಪ್ರತಿ ಯೋಜನೆಗೆ ನಿಮ್ಮನ್ನು ನೋಂದಾಯಿಸುತ್ತಾರೆ.",
  "vn.enrol.step4t": "ಇ-ರೂಪಾಯಿ ಸ್ವೀಕರಿಸಲು ಪ್ರಾರಂಭಿಸಿ",
  "vn.enrol.step4d": "ನೋಂದಣಿಯ ನಂತರ, ಆ ಯೋಜನೆಗಳ ನಾಗರಿಕರು ನಿಮಗೆ ನೇರವಾಗಿ ಡಿಜಿಟಲ್ ರೂಪಾಯಿಯಲ್ಲಿ ಪಾವತಿಸಬಹುದು.",
  "vn.enrol.contact": "ಮಾರಾಟಗಾರರಾಗಿ ಸೇರಲು, ನಿಮ್ಮ ವ್ಯಾಪಾರ ನೋಂದಣಿ ವಿವರಗಳೊಂದಿಗೆ ಯೋಜನೆ ಆಡಳಿತವನ್ನು ಸಂಪರ್ಕಿಸಿ. ರಿಜಿಸ್ಟ್ರಿಯನ್ನು ವಿಶ್ವಾಸಾರ್ಹವಾಗಿಡಲು ನೋಂದಣಿಯನ್ನು ಕೇಂದ್ರೀಯವಾಗಿ ಮಾಡಲಾಗುತ್ತದೆ.",
  "vn.enrol.formTitle": "ನಿಮ್ಮ ವ್ಯಾಪಾರವನ್ನು ನೋಂದಾಯಿಸಿ",
  "vn.enrol.formHint": "ಸರ್ಕಾರಿ ವ್ಯಾಪಾರ ರಿಜಿಸ್ಟ್ರಿಯಲ್ಲಿ ನಮೂದಾದ ಹೆಸರಿನಂತೆ ನಿಮ್ಮ ವ್ಯಾಪಾರವನ್ನು ನಮೂದಿಸಿ. ಅನುಮೋದನೆಗೆ ಮೊದಲು ನಾವು ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಹೊಂದಿಸಿ ಪರಿಶೀಲಿಸುತ್ತೇವೆ.",
  "vn.enrol.bizName": "ನೋಂದಾಯಿತ ವ್ಯಾಪಾರ ಹೆಸರು",
