  "vn.dash.howPaidBody": "ਨਾਗਰਿਕ ਆਪਣਾ ਲਾਭ ਸਿੱਧਾ ਈ-ਰੁਪਇਆ ਵਿੱਚ ਤੁਹਾਡੇ ਨਾਲ ਖਰਚਦੇ ਹਨ। ਡਿਲੀਵਰੀ ਦੀ ਪੁਸ਼ਟੀ ਤੋਂ ਬਾਅਦ, ਇੱਕ ਪ੍ਰਸ਼ਾਸਕ ਤੁਹਾਡੇ ਵੱਲੋਂ ਮੋਚਨ ਦਾਖਲ ਕਰਦਾ ਹੈ ਅਤੇ ਰਿਜ਼ਰਵ ਬੈਂਕ ਇਸਨੂੰ ਨਕਦ ਵਿੱਚ ਨਿਪਟਾਉਂਦਾ ਹੈ — ਵੇਖੋ",
