  "vn.enrol.sub": "ਮਨਜ਼ੂਰਸ਼ੁਦਾ ਵਿਕਰੇਤਾ BharatChain ਯੋਜਨਾਵਾਂ ਵਿੱਚ ਕਿਵੇਂ ਸ਼ਾਮਲ ਹੁੰਦੇ ਹਨ।",
