  "vn.enrol.notEnrolledBody": "ਤੁਹਾਡਾ ਖਾਤਾ ਮਨਜ਼ੂਰਸ਼ੁਦਾ ਵਿਕਰੇਤਾ ਰਿਕਾਰਡ ਨਾਲ ਜੁੜਿਆ ਨਹੀਂ ਹੈ। ਵਿਕਰੇਤਾ ਦਾਖਲਾ ZK ਕਾਰੋਬਾਰ-ਰਜਿਸਟਰੀ ਜਾਂਚ ਤੋਂ ਬਾਅਦ ਯੋਜਨਾ ਪ੍ਰਸ਼ਾਸਕਾਂ ਦੁਆਰਾ ਸ਼ੁਰੂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
