  "vn.enrol.step1d": "ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਪ੍ਰਮਾਣ ਯੋਜਨਾ ਦੇ ਖੇਤਰ ਲਈ ਰੱਖੀ ਸਰਕਾਰੀ ਕਾਰੋਬਾਰ ਰਜਿਸਟਰੀ ਨਾਲ ਮਿਲਾਏ ਜਾਂਦੇ ਹਨ।",
  "vn.enrol.step2t": "ਜ਼ੀਰੋ-ਨਾਲੇਜ ਪਰੂਫ",
  "vn.enrol.step2d": "ਇੱਕ ਸਬੂਤ ਬਣਦਾ ਹੈ ਕਿ ਤੁਹਾਡਾ ਕਾਰੋਬਾਰ ਸ਼੍ਰੇਣੀ ਲਈ ਯੋਗ ਹੈ — ਤੁਹਾਡੇ ਨਿੱਜੀ ਕਾਰੋਬਾਰ ਡਾਟਾ ਨੂੰ ਜ਼ਾਹਰ ਕੀਤੇ ਬਿਨਾਂ।",
  "vn.enrol.step3t": "ਆਨ-ਚੇਨ ਰਿਲੇ",
  "vn.enrol.step3d": "ਇੱਕ ਯੋਜਨਾ ਪ੍ਰਸ਼ਾਸਕ ਤਸਦੀਕਸ਼ੁਦਾ ਸਬੂਤ ਰਿਲੇ ਕਰਦਾ ਹੈ, ਤੁਹਾਨੂੰ ਹਰ ਉਸ ਯੋਜਨਾ ਵਿੱਚ ਦਾਖਲ ਕਰਦਾ ਹੈ ਜਿਸਦੀ ਤੁਹਾਡੀ ਸ਼੍ਰੇਣੀ ਸੇਵਾ ਕਰ ਸਕਦੀ ਹੈ।",
  "vn.enrol.step4t": "ਈ-ਰੁਪਇਆ ਸਵੀਕਾਰ ਕਰਨਾ ਸ਼ੁਰੂ ਕਰੋ",
  "vn.enrol.step4d": "ਦਾਖਲੇ ਤੋਂ ਬਾਅਦ, ਉਨ੍ਹਾਂ ਯੋਜਨਾਵਾਂ ਦੇ ਨਾਗਰਿਕ ਤੁਹਾਨੂੰ ਸਿੱਧਾ ਡਿਜੀਟਲ ਰੁਪਇਆ ਵਿੱਚ ਭੁਗਤਾਨ ਕਰ ਸਕਦੇ ਹਨ।",
  "vn.enrol.contact": "ਵਿਕਰੇਤਾ ਵਜੋਂ ਜੁੜਨ ਲਈ, ਆਪਣੇ ਕਾਰੋਬਾਰ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਵੇਰਵਿਆਂ ਨਾਲ ਯੋਜਨਾ ਪ੍ਰਸ਼ਾਸਨ ਨਾਲ ਸੰਪਰਕ ਕਰੋ। ਰਜਿਸਟਰੀ ਨੂੰ ਭਰੋਸੇਯੋਗ ਰੱਖਣ ਲਈ ਦਾਖਲਾ ਕੇਂਦਰੀ ਤੌਰ 'ਤੇ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
