  "vn.dash.noServeTitle": "କୌଣସି ସେବାଯୋଗ୍ୟ ଯୋଜନା ନାହିଁ",
  "vn.dash.noServeNote": "ବର୍ତ୍ତମାନ କୌଣସି ସକ୍ରିୟ ଯୋଜନା ଆପଣଙ୍କ ବିକ୍ରେତା ବର୍ଗ ସହ ମେଳ ଖାଉନାହିଁ।",
  "vn.dash.perInstallment": "/ କିସ୍ତି",
  "vn.dash.howPaid": "ଆପଣ କିପରି ଦେୟ ପାଆନ୍ତି:",
  "vn.dash.howPaidBody": "ନାଗରିକମାନେ ସେମାନଙ୍କ ଲାଭ ସିଧାସଳଖ ଇ-ଟଙ୍କାରେ ଆପଣଙ୍କ ସହ ଖର୍ଚ୍ଚ କରନ୍ତି। ସେମାନେ ବିତରଣ ନିଶ୍ଚିତ କଲା ପରେ, ଜଣେ ପ୍ରଶାସକ ଆପଣଙ୍କ ତରଫରୁ ମୋଚନ ଦାଖଲ କରନ୍ତି ଏବଂ ରିଜର୍ଭ ବ୍ୟାଙ୍କ ଏହାକୁ ନଗଦରେ ସମାଧାନ କରେ — ଦେଖନ୍ତୁ",
  "vn.enrol.title": "ନାମାଙ୍କନ",
  "vn.enrol.sub": "ଅନୁମୋଦିତ ବିକ୍ରେତାମାନେ BharatChain ଯୋଜନାରେ କିପରି ଯୋଗ ଦିଅନ୍ତି।",
  "vn.enrol.enrolled": "ଆପଣ ନାମାଙ୍କିତ",
  "vn.enrol.notEnrolled": "ଏ ପର୍ଯ୍ୟନ୍ତ ନାମାଙ୍କିତ ନୁହଁନ୍ତି",
  "vn.enrol.enrolledBody": "{cat} ଭାବେ ଅନୁମୋଦିତ। ଆପଣ {n}ଟି ସକ୍ରିୟ ଯୋଜନାରୁ ଇ-ଟଙ୍କା ଗ୍ରହଣ କରିପାରିବେ।",
  "vn.enrol.notEnrolledBody": "ଆପଣଙ୍କ ଆକାଉଣ୍ଟ ଅନୁମୋଦିତ ବିକ୍ରେତା ରେକର୍ଡ ସହ ଲିଙ୍କ ହୋଇନାହିଁ। ବିକ୍ରେତା ନାମାଙ୍କନ ଗୋଟିଏ ZK ବ୍ୟବସାୟ-ରେଜିଷ୍ଟ୍ରି ଯାଞ୍ଚ ପରେ ଯୋଜନା ପ୍ରଶାସକଙ୍କ ଦ୍ୱାରା ଆରମ୍ଭ କରାଯାଏ।",
  "vn.enrol.howTitle": "ନାମାଙ୍କନ କିପରି କାମ କରେ",
  "vn.enrol.step1t": "ବ୍ୟବସାୟ ରେଜିଷ୍ଟ୍ରି ମେଳ",
  "vn.enrol.step1d": "ଆପଣଙ୍କ ବ୍ୟବସାୟ ପ୍ରମାଣପତ୍ର ଯୋଜନାର କ୍ଷେତ୍ର ପାଇଁ ରଖାଯାଇଥିବା ସରକାରୀ ବ୍ୟବସାୟ ରେଜିଷ୍ଟ୍ରି ସହ ମିଳାଯାଏ।",
  "vn.enrol.step2t": "ଜିରୋ-ନଲେଜ ପ୍ରୁଫ",
  "vn.enrol.step2d": "ଆପଣଙ୍କ ବ୍ୟବସାୟ ବର୍ଗ ପାଇଁ ଯୋଗ୍ୟ ବୋଲି ଗୋଟିଏ ପ୍ରମାଣ ତିଆରି ହୁଏ — ଆପଣଙ୍କ ବ୍ୟକ୍ତିଗତ ବ୍ୟବସାୟ ତଥ୍ୟ ପ୍ରକାଶ ନକରି।",
  "vn.enrol.step3t": "ଅନ-ଚେନ ରିଲେ",
  "vn.enrol.step3d": "ଜଣେ ଯୋଜନା ପ୍ରଶାସକ ଯାଞ୍ଚିତ ପ୍ରମାଣ ରିଲେ କରନ୍ତି, ଆପଣଙ୍କ ବର୍ଗ ସେବା କରିପାରୁଥିବା ପ୍ରତ୍ୟେକ ଯୋଜନାରେ ଆପଣଙ୍କୁ ନାମାଙ୍କିତ କରନ୍ତି।",
  "vn.enrol.step4t": "ଇ-ଟଙ୍କା ଗ୍ରହଣ ଆରମ୍ଭ କରନ୍ତୁ",
  "vn.enrol.step4d": "ନାମାଙ୍କନ ପରେ, ସେହି ଯୋଜନାର ନାଗରିକମାନେ ଆପଣଙ୍କୁ ସିଧାସଳଖ ଡିଜିଟାଲ ଟଙ୍କାରେ ଦେୟ ଦେଇପାରିବେ।",
  "vn.enrol.contact": "ବିକ୍ରେତା ଭାବେ ଯୋଗ ଦେବାକୁ, ଆପଣଙ୍କ ବ୍ୟବସାୟ ପଞ୍ଜୀକରଣ ବିବରଣୀ ସହ ଯୋଜନା ପ୍ରଶାସନ ସହ ଯୋଗାଯୋଗ କରନ୍ତୁ। ରେଜିଷ୍ଟ୍ରିକୁ ବିଶ୍ୱସନୀୟ ରଖିବାକୁ ନାମାଙ୍କନ କେନ୍ଦ୍ରୀୟ ଭାବେ କରାଯାଏ।",
  "vn.enrol.formTitle": "ଆପଣଙ୍କ ବ୍ୟବସାୟ ପଞ୍ଜୀକରଣ କରନ୍ତୁ",
  "vn.enrol.formHint": "ସରକାରୀ ବ୍ୟବସାୟ ରେଜିଷ୍ଟ୍ରିରେ ତାଲିକାଭୁକ୍ତ ନାମ ଅନୁଯାୟୀ ଆପଣଙ୍କ ବ୍ୟବସାୟ ଲେଖନ୍ତୁ। ଅନୁମୋଦନ ପୂର୍ବରୁ ଆମେ ଆପଣଙ୍କ ବିବରଣୀ ମିଳାଇ ସମୀକ୍ଷା କରିବୁ।",
